function control(state) {
  var tip = state.tip;
  var target = state.target;
  if (!Array.isArray(tip) || !Array.isArray(target) || tip.length < 2 || target.length < 2) {
    return { action: "stop", reason: "invalid tip or target" };
  }
  var ex = target[0] - tip[0];
  var ey = target[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) {
    return { action: "stop", reason: "non-finite error" };
  }
  if (err <= state.tolerancePx) {
    return { action: "verify" };
  }

  var hist = (state.history || []).slice(-30);
  var n = hist.length;

  // Weighted least squares over recent samples using ACKed (applied) inputs.
  var A = [[0, 0], [0, 0]];
  var B = [[0, 0], [0, 0]];
  var valid = 0;
  for (var i = 0; i < n; i++) {
    var h = hist[i];
    if (!h || !h.applied || !h.delta) continue;
    var c = h.applied;
    var d = h.delta;
    if (!isFinite(c[0]) || !isFinite(c[1]) || !isFinite(d[0]) || !isFinite(d[1])) continue;
    var w = Math.pow(0.9, n - 1 - i);
    valid++;
    for (var p = 0; p < 2; p++) {
      for (var q = 0; q < 2; q++) {
        A[p][q] += w * c[p] * c[q];
      }
      B[0][p] += w * d[0] * c[p];
      B[1][p] += w * d[1] * c[p];
    }
  }
  A[0][0] += 1e-6;
  A[1][1] += 1e-6;
  var detA = A[0][0] * A[1][1] - A[0][1] * A[1][0];
  var trA = A[0][0] + A[1][1];
  var J = null;
  if (valid >= 3 && detA / (trA * trA + 1e-12) > 0.02) {
    var Ai = [[A[1][1] / detA, -A[0][1] / detA], [-A[1][0] / detA, A[0][0] / detA]];
    J = [
      [B[0][0] * Ai[0][0] + B[0][1] * Ai[1][0], B[0][0] * Ai[0][1] + B[0][1] * Ai[1][1]],
      [B[1][0] * Ai[0][0] + B[1][1] * Ai[1][0], B[1][0] * Ai[0][1] + B[1][1] * Ai[1][1]]
    ];
    if (!isFinite(J[0][0]) || !isFinite(J[0][1]) || !isFinite(J[1][0]) || !isFinite(J[1][1])) {
      J = null;
    }
  }

  // Limit detection from the most recent sample.
  var lim = [false, false];
  var lastCmd = [0, 0];
  if (n > 0 && hist[n - 1] && hist[n - 1].command && hist[n - 1].applied) {
    var lc = hist[n - 1].command;
    var la = hist[n - 1].applied;
    lastCmd = [lc[0], lc[1]];
    for (var k = 0; k < 2; k++) {
      if (Math.abs(lc[k]) > 1e-9 && Math.abs(la[k]) < 0.5 * Math.abs(lc[k])) {
        lim[k] = true;
      }
    }
  }

  var u;
  if (J === null) {
    // Probe the less-excited channel; reverse it if it was just limited.
    var ch = (A[0][0] <= A[1][1]) ? 0 : 1;
    var s = 1;
    if (lim[ch] && Math.abs(lastCmd[ch]) > 1e-9) {
      s = lastCmd[ch] > 0 ? -1 : 1;
    }
    u = [0, 0];
    u[ch] = 0.1 * s;
    return { action: "move", u: u };
  }

  var detJ = J[0][0] * J[1][1] - J[0][1] * J[1][0];
  if (!isFinite(detJ) || Math.abs(detJ) < 1e-9) {
    var ch2 = (A[0][0] <= A[1][1]) ? 0 : 1;
    var s2 = 1;
    if (lim[ch2] && Math.abs(lastCmd[ch2]) > 1e-9) {
      s2 = lastCmd[ch2] > 0 ? -1 : 1;
    }
    u = [0, 0];
    u[ch2] = 0.1 * s2;
    return { action: "move", u: u };
  }

  var Jinv = [[J[1][1] / detJ, -J[0][1] / detJ], [-J[1][0] / detJ, J[0][0] / detJ]];
  var raw = [
    Jinv[0][0] * ex + Jinv[0][1] * ey,
    Jinv[1][0] * ex + Jinv[1][1] * ey
  ];

  var limitedCh = -1;
  if (lim[0] && !lim[1]) limitedCh = 0;
  else if (lim[1] && !lim[0]) limitedCh = 1;
  else if (lim[0] && lim[1]) limitedCh = (Math.abs(raw[0]) >= Math.abs(raw[1])) ? 0 : 1;

  if (limitedCh >= 0) {
    // Joint at travel limit: retreat that channel and solve the other one,
    // so the arm unfolds instead of pushing the elbow further into its stop.
    var i0 = limitedCh;
    var j0 = 1 - i0;
    var ui = (lastCmd[i0] > 0) ? -0.1 : 0.1;
    var rx = ex - J[0][i0] * ui;
    var ry = ey - J[1][i0] * ui;
    var colJ0 = J[0][j0];
    var colJ1 = J[1][j0];
    var nn = colJ0 * colJ0 + colJ1 * colJ1 + 1e-9;
    var uj = (colJ0 * rx + colJ1 * ry) / nn;
    u = [0, 0];
    u[i0] = ui;
    u[j0] = uj;
  } else {
    u = raw;
  }

  if (!isFinite(u[0]) || !isFinite(u[1])) {
    return { action: "stop", reason: "non-finite control" };
  }
  var m = Math.max(Math.abs(u[0]), Math.abs(u[1]));
  if (m > 0.1) {
    u = [u[0] * 0.1 / m, u[1] * 0.1 / m];
  }
  u = [Math.max(-0.1, Math.min(0.1, u[0])), Math.max(-0.1, Math.min(0.1, u[1]))];
  return { action: "move", u: u };
}

function control(state) {
  var tol = state.tolerancePx;
  var tip = state.tip, tg = state.target;
  var ex = tg[0] - tip[0], ey = tg[1] - tip[1];
  var dist = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(dist)) return { action: "stop", reason: "non-finite error" };
  if (dist <= tol) return { action: "verify" };
  var h = state.history || [];
  var n0 = h.length;
  var probes = [[0.1, 0], [0, 0.1], [-0.1, 0], [0, -0.1]];
  var start = Math.max(0, n0 - 24);
  var c11 = 0, c12 = 0, c22 = 0, d11 = 0, d12 = 0, d21 = 0, d22 = 0, cnt = 0;
  for (var i = start; i < n0; i++) {
    var s = h[i];
    if (!s || !s.delta || !s.applied) continue;
    var a = s.applied[0], b = s.applied[1], dx = s.delta[0], dy = s.delta[1];
    if (!isFinite(a) || !isFinite(b) || !isFinite(dx) || !isFinite(dy)) continue;
    if (Math.abs(a) + Math.abs(b) < 1e-9) continue;
    var w = Math.pow(0.9, n0 - 1 - i);
    c11 += w * a * a; c12 += w * a * b; c22 += w * b * b;
    d11 += w * dx * a; d12 += w * dx * b; d21 += w * dy * a; d22 += w * dy * b;
    cnt++;
  }
  var lam = 1e-9;
  var m11 = c11 + lam, m12 = c12, m22 = c22 + lam;
  var mdet = m11 * m22 - m12 * m12;
  var u = null;
  if (cnt >= 3 && isFinite(mdet) && Math.abs(mdet) > 1e-12) {
    var i11 = m22 / mdet, i12 = -m12 / mdet, i22 = m11 / mdet;
    var J11 = d11 * i11 + d12 * i12, J12 = d11 * i12 + d12 * i22;
    var J21 = d21 * i11 + d22 * i12, J22 = d21 * i12 + d22 * i22;
    var jdet = J11 * J22 - J12 * J21;
    var fro2 = J11 * J11 + J12 * J12 + J21 * J21 + J22 * J22;
    if (fro2 > 0 && isFinite(jdet) && Math.abs(jdet) > 1e-12 && (jdet * jdet) / (fro2 * fro2) > 0.01) {
      var g = dist < 3 * tol ? 0.5 : 0.8;
      var c1 = g * (J22 * ex - J12 * ey) / jdet;
      var c2 = g * (-J21 * ex + J11 * ey) / jdet;
      if (isFinite(c1) && isFinite(c2)) u = [c1, c2];
    }
  }
  if (!u) {
    u = probes[n0 % 4].slice();
  }
  // Elbow/limit handling: if a channel was reduced by the device recently, retreat from its limit.
  for (var ch = 0; ch < 2; ch++) {
    var sign = 0;
    for (var k = Math.max(0, n0 - 2); k < n0; k++) {
      var sk = h[k];
      if (!sk || !sk.command || !sk.applied || !sk.limited) continue;
      var cmd = sk.command[ch], app = sk.applied[ch];
      if (!isFinite(cmd) || !isFinite(app)) continue;
      if (Math.abs(cmd) > 1e-9 && Math.abs(app) < Math.abs(cmd) - 1e-9) {
        sign = cmd > 0 ? 1 : -1;
      }
    }
    if (sign !== 0) u[ch] = -sign * 0.1;
  }
  var mx = Math.max(Math.abs(u[0]), Math.abs(u[1]));
  if (mx > 0.1) { u[0] = u[0] * 0.1 / mx; u[1] = u[1] * 0.1 / mx; }
  if (!isFinite(u[0]) || !isFinite(u[1])) return { action: "stop", reason: "non-finite command" };
  return { action: "move", u: [u[0], u[1]] };
}

function control(state) {
  var tip = state.tip, tgt = state.target;
  if (!tip || !tgt || !isFinite(tip[0]) || !isFinite(tip[1]) || !isFinite(tgt[0]) || !isFinite(tgt[1])) {
    return { action: "stop", reason: "non-finite input" };
  }
  var ex = tgt[0] - tip[0], ey = tgt[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) return { action: "stop", reason: "non-finite error" };
  var tol = (typeof state.tolerancePx === "number" && state.tolerancePx > 0) ? state.tolerancePx : 7;
  if (err <= tol) return { action: "verify" };

  var H = state.history || [];
  var n = H.length;
  var start = Math.max(0, n - 40);
  var M00 = 0, M01 = 0, M11 = 0;
  var R0 = [0, 0], R1 = [0, 0];
  var cnt = 0;
  for (var i = start; i < n; i++) {
    var h = H[i];
    if (!h || !h.applied || !h.delta) continue;
    var a = h.applied, d = h.delta;
    if (!isFinite(a[0]) || !isFinite(a[1]) || !isFinite(d[0]) || !isFinite(d[1])) continue;
    if (Math.abs(a[0]) + Math.abs(a[1]) < 1e-6) continue;
    var w = 0.4 + 0.6 * (i - start + 1) / (n - start);
    M00 += w * a[0] * a[0];
    M01 += w * a[0] * a[1];
    M11 += w * a[1] * a[1];
    R0[0] += w * a[0] * d[0]; R0[1] += w * a[1] * d[0];
    R1[0] += w * a[0] * d[1]; R1[1] += w * a[1] * d[1];
    cnt++;
  }

  var tr = M00 + M11;
  var det0 = M00 * M11 - M01 * M01;
  var excited = cnt >= 3 && M00 > 1e-4 && M11 > 1e-4 && tr > 1e-6 && det0 > 0.02 * tr * tr;

  if (!excited) {
    var probes = [[0.1, 0], [0, 0.1], [-0.1, 0], [0, -0.1]];
    var pr = probes[n % 4];
    return { action: "move", u: [pr[0], pr[1]] };
  }

  // Ridge-regularized local Jacobian: delta ≈ J * applied
  var lam = 1e-3 * tr + 1e-12;
  var A00 = M00 + lam, A11 = M11 + lam, A01 = M01;
  var dA = A00 * A11 - A01 * A01;
  if (!isFinite(dA) || Math.abs(dA) < 1e-14) {
    var pr3 = probes[n % 4];
    return { action: "move", u: [pr3[0], pr3[1]] };
  }
  var i00 = A11 / dA, i01 = -A01 / dA, i11 = A00 / dA;
  var jx0 = i00 * R0[0] + i01 * R0[1];
  var jx1 = i01 * R0[0] + i11 * R0[1];
  var jy0 = i00 * R1[0] + i01 * R1[1];
  var jy1 = i01 * R1[0] + i11 * R1[1];

  // Desired pixel displacement, capped when far away
  var scaleD = Math.min(1, 30 / err);
  var dx = ex * scaleD, dy = ey * scaleD;

  // Damped least-squares: u = (J^T J + mu I)^-1 J^T d
  var JTJ00 = jx0 * jx0 + jy0 * jy0;
  var JTJ01 = jx0 * jx1 + jy0 * jy1;
  var JTJ11 = jx1 * jx1 + jy1 * jy1;
  var mu = 0.01 * (JTJ00 + JTJ11) + 1e-9;
  var B00 = JTJ00 + mu, B01 = JTJ01, B11 = JTJ11 + mu;
  var bdet = B00 * B11 - B01 * B01;
  if (!isFinite(bdet) || Math.abs(bdet) < 1e-18) {
    var pr4 = probes[n % 4];
    return { action: "move", u: [pr4[0], pr4[1]] };
  }
  var rhs0 = jx0 * dx + jy0 * dy;
  var rhs1 = jx1 * dx + jy1 * dy;
  var u0 = (B11 * rhs0 - B01 * rhs1) / bdet;
  var u1 = (-B01 * rhs0 + B00 * rhs1) / bdet;
  if (!isFinite(u0) || !isFinite(u1)) return { action: "stop", reason: "non-finite solve" };

  // Elbow / joint limit retreat: if a channel was pinned in the last two samples, back it off
  var u = [u0, u1];
  if (n >= 2) {
    var h1 = H[n - 1], h2 = H[n - 2];
    if (h1 && h2 && h1.command && h2.command && h1.applied && h2.applied && h1.limited && h2.limited) {
      for (var k = 0; k < 2; k++) {
        var c1 = h1.command[k], c2 = h2.command[k];
        if (Math.abs(c1) > 1e-6 && Math.abs(h1.applied[k]) < 0.5 * Math.abs(c1) &&
            Math.abs(c2) > 1e-6 && Math.abs(h2.applied[k]) < 0.5 * Math.abs(c2)) {
          u[k] = (c1 > 0 ? -0.1 : 0.1);
        }
      }
    }
  }
  u0 = u[0]; u1 = u[1];

  var m = Math.max(Math.abs(u0), Math.abs(u1));
  if (m < 1e-9) {
    var pr5 = probes[n % 4];
    return { action: "move", u: [pr5[0], pr5[1]] };
  }
  if (m > 0.1) { u0 *= 0.1 / m; u1 *= 0.1 / m; }
  var floor = err > 3 * tol ? 0.02 : 0.01;
  m = Math.max(Math.abs(u0), Math.abs(u1));
  if (m < floor) { u0 *= floor / m; u1 *= floor / m; }

  u0 = Math.max(-0.1, Math.min(0.1, u0));
  u1 = Math.max(-0.1, Math.min(0.1, u1));
  if (!isFinite(u0) || !isFinite(u1)) return { action: "stop", reason: "non-finite output" };
  return { action: "move", u: [u0, u1] };
}

function inv2(M) {
  var d = M[0][0] * M[1][1] - M[0][1] * M[1][0];
  if (!isFinite(d) || Math.abs(d) < 1e-12) return null;
  return [[M[1][1] / d, -M[0][1] / d], [-M[1][0] / d, M[0][0] / d]];
}

function mul2(A, B) {
  return [
    [A[0][0] * B[0][0] + A[0][1] * B[1][0], A[0][0] * B[0][1] + A[0][1] * B[1][1]],
    [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]]
  ];
}

function blockedFromHistory(h) {
  var blocked = [[false, false], [false, false]];
  var start = Math.max(0, h.length - 6);
  for (var i = start; i < h.length; i++) {
    var s = h[i];
    if (!s || !s.command || !s.limited) continue;
    var a = s.applied || s.command;
    for (var k = 0; k < 2; k++) {
      var c = s.command[k];
      if (Math.abs(c) < 1e-9) continue;
      if (Math.abs(a[k]) < 0.5 * Math.abs(c)) {
        blocked[k][c > 0 ? 0 : 1] = true;
      }
    }
  }
  return blocked;
}

function isBlockedMove(u, blocked) {
  for (var k = 0; k < 2; k++) {
    if (u[k] > 0 && blocked[k][0]) return true;
    if (u[k] < 0 && blocked[k][1]) return true;
  }
  return false;
}

function explore(h, err, dist, blocked) {
  var cands = [[0.1, 0], [0, 0.1], [-0.1, 0], [0, -0.1]];
  var best = 0, bestScore = Infinity;
  for (var k = 0; k < cands.length; k++) {
    var c = cands[k];
    var count = 0;
    for (var i = 0; i < h.length; i++) {
      var s = h[i];
      if (!s || !s.command) continue;
      var cm = s.command;
      var nc = Math.sqrt(cm[0] * cm[0] + cm[1] * cm[1]);
      if (nc < 1e-9) continue;
      var cos = (cm[0] * c[0] + cm[1] * c[1]) / (nc * 0.1);
      if (Math.abs(cos) > 0.7) count += s.limited ? 2 : 1;
    }
    var dot = dist > 0 ? (c[0] * err[0] + c[1] * err[1]) / dist : 0;
    var score = count + (dot < 0 ? 0.5 : 0);
    if (isBlockedMove(c, blocked)) score += 1000;
    if (score < bestScore) { bestScore = score; best = k; }
  }
  return { action: "move", u: [cands[best][0], cands[best][1]] };
}

function control(state) {
  var tip = state.tip, target = state.target;
  var ex = target[0] - tip[0], ey = target[1] - tip[1];
  var dist = Math.sqrt(ex * ex + ey * ey);
  if (!(dist > state.tolerancePx)) return { action: "verify" };
  var err = [ex, ey];
  var h = state.history || [];
  var n = h.length;
  var blocked = blockedFromHistory(h);

  var saa = [[0, 0], [0, 0]];
  var sya = [[0, 0], [0, 0]];
  var cnt = 0;
  for (var i = 0; i < n; i++) {
    var s = h[i];
    if (!s || !s.delta) continue;
    var a = s.applied || s.command;
    var y = s.delta;
    if (!a || a.length !== 2 || !y || y.length !== 2) continue;
    if (!isFinite(a[0]) || !isFinite(a[1]) || !isFinite(y[0]) || !isFinite(y[1])) continue;
    if (Math.abs(a[0]) + Math.abs(a[1]) < 1e-9) continue;
    var w = Math.pow(0.92, n - 1 - i);
    for (var r = 0; r < 2; r++) {
      for (var c = 0; c < 2; c++) {
        saa[r][c] += w * a[r] * a[c];
        sya[r][c] += w * y[r] * a[c];
      }
    }
    cnt++;
  }
  if (cnt < 3) return explore(h, err, dist, blocked);

  // ridge regularization keeps the local estimate stable near limits
  saa[0][0] += 0.002;
  saa[1][1] += 0.002;

  var Sinv = inv2(saa);
  if (!Sinv) return explore(h, err, dist, blocked);
  var J = mul2(sya, Sinv);
  var Jinv = inv2(J);
  if (!Jinv) return explore(h, err, dist, blocked);

  var u0 = 0.8 * (Jinv[0][0] * ex + Jinv[0][1] * ey);
  var u1 = 0.8 * (Jinv[1][0] * ex + Jinv[1][1] * ey);
  if (!isFinite(u0) || !isFinite(u1)) return explore(h, err, dist, blocked);

  // zero out components that would push into a known limit
  if (u0 > 0 && blocked[0][0]) u0 = 0;
  if (u0 < 0 && blocked[0][1]) u0 = 0;
  if (u1 > 0 && blocked[1][0]) u1 = 0;
  if (u1 < 0 && blocked[1][1]) u1 = 0;
  if (Math.abs(u0) + Math.abs(u1) < 1e-9) return explore(h, err, dist, blocked);

  var m = Math.max(Math.abs(u0), Math.abs(u1));
  if (m > 0.1) { u0 *= 0.1 / m; u1 *= 0.1 / m; }
  if (m < 0.01) { u0 *= 0.01 / m; u1 *= 0.01 / m; }
  if (Math.abs(u0) > 0.1) u0 = u0 > 0 ? 0.1 : -0.1;
  if (Math.abs(u1) > 0.1) u1 = u1 > 0 ? 0.1 : -0.1;
  return { action: "move", u: [u0, u1] };
}

function control(state) {
  var tol = state.tolerancePx;
  var tip = state.tip, tgt = state.target;
  if (!tip || !tgt || tip.length < 2 || tgt.length < 2) {
    return { action: "stop", reason: "missing tip or target" };
  }
  var ex = tgt[0] - tip[0], ey = tgt[1] - tip[1];
  var dist = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(dist)) {
    return { action: "stop", reason: "non-finite error" };
  }
  if (dist <= tol) {
    return { action: "verify" };
  }
  var h = state.history || [];
  var n = h.length;

  // Travel-limit detection: newest non-zero command per channel decides whether
  // that channel is currently blocked in the commanded direction.
  var blocked = [0, 0];
  var decided = [false, false];
  for (var i = n - 1; i >= 0; i--) {
    var s = h[i];
    if (!s || !s.command || !s.applied) continue;
    for (var k = 0; k < 2; k++) {
      if (decided[k]) continue;
      var c = s.command[k], ap = s.applied[k];
      if (!isFinite(c) || !isFinite(ap) || Math.abs(c) < 1e-9) continue;
      decided[k] = true;
      if (s.limited && Math.abs(ap) < 0.5 * Math.abs(c)) {
        blocked[k] = c > 0 ? 1 : -1;
      }
    }
  }

  // Local Jacobian fit from recent measured samples (limited samples use their
  // actual applied value, so they still constrain the mapping).
  var M00 = 0, M01 = 0, M11 = 0;
  var N00 = 0, N01 = 0, N10 = 0, N11 = 0;
  var used = 0, cnt = [0, 0];
  for (var j = n - 1; j >= 0 && used < 40; j--) {
    var t = h[j];
    if (!t || !t.applied || !t.delta) continue;
    var a0 = t.applied[0], a1 = t.applied[1];
    var d0 = t.delta[0], d1 = t.delta[1];
    if (!isFinite(a0) || !isFinite(a1) || !isFinite(d0) || !isFinite(d1)) continue;
    if (Math.abs(a0) + Math.abs(a1) < 1e-9) continue;
    var w = Math.pow(0.85, used);
    used++;
